head.script:
// 테스트 설명, 유효성 값 설정
scwin.tData = {
    "description" : "[autoComplete > M > setGridItemset]<br/>아이템이 GridViewItemSet 으로 정의되었을때 아이템과 DataCollection 을 새롭게 바인딩합니다.",
    "validation" : [
        "GridViewItemSet 은 renderType=component 인 경우만 지원합니다.",
        "디자인 시 GridViewItemSet 으로 아이템을 정의한 컴포넌트일때 메소드 실행 후 아이템 리스트가 정상적으로 표시됩니다.",
        "info(필수) 파라미터로 새로 바인딩할 DataCollection 정보를 객체로 설정합니다.",
        "info.nodeset(필수) 파라미터로 아이템이 정의된 DataCollection 의 ID 를 'data:[DataCollection ID]' 형식으로 설정합니다.",
        "info.label(필수) 파라미터로 아이템의 Label 값과 바인딩 될 컬럼의 ID 를 문자열로 설정합니다.",
        "info.value(필수) 파라미터로 아이템의 Value 값과 바인딩 될 컬럼의 ID 를 문자열로 설정합니다.",
        "info.width(선택) 파라미터로 아이템 리스트창의 너비를 픽셀단위 숫자로 설정합니다.",
        "info.width(선택) 파라미터 값을 설정하지 않으면 컴포넌트의 너비가 적용됩니다.",
        "info.height(선택) 파라미터로 아이템 리스트창의 높이를 픽셀단위 숫자로 설정합니다.",
        "info.height(선택) 파라미터는 visibleRowNum 속성이 우선 적용되어 설정값은 적용되지 않습니다.",
        "info.item(필수) 파라미터로 아이템 리스트창의 GridView 와 맵핑될 컬럼들의 정보를 객체의 배열로 설정합니다.",
        "info.item(필수) 파라미터 설정 시 배열에 정의된 순서대로 컬럼이 생성됩니다.",
        "item.ref(필수) 파라미터로 아이템 리스트창의 컬럼과 맵핑될 컬럼의 ID 를 설정합니다.",
        "item.header(필수) 파라미터로 아이템 리스트창의 컬럼 헤더에 표시될 텍스트를 설정합니다.",
        "setGridItemset() 메소드는 기존의 GridViewItemSet 정보를 모두 삭제하고 새로 설정합니다.",
    ]
}



scwin.onpageload = function () {
    // Global DataList 생성 호출
    $c.gcm.createCommonDatalist();

    // 테스트 설명, 유효성 생성
    wf_body_left.getObj("scwin").createValidation(scwin.tData);

    // comp 초기 생성
    scwin.comp_init();
};



// comp 생성
scwin.comp_init = async function () {
    let data1 = [];
    let data2 = [];

    let row = 2;
    let col = 3;
    for (let i = 0; i < row; i++) {
        for (let j = 0; j < col ; j++) {
            if( j === 0 ) {
                data1.push("o_label=" + String(i));
                data2.push("n_label=" + String(i));                
            } else if (j === 1) {
                data1.push("o_value=" + String(i));
                data2.push("n_value=" + String(i));                
            } else {
                data1.push("o_user=" + String(i));
                data2.push("n_user=" + String(i));                
            }
        }
    }
    dataList1.setData(data1);
    dataList2.setData(data2);    
}


// DataCollection 정보 설정
var info = {
    "nodeset" : "data:dataList2",
    "label" : "label",
    "value" : "value",
    "width" : 210,
    "height" : 200,    
    "item" : [
        {"ref" : "label", "header" : "nLabel"},
        {"ref" : "value", "header" : "nValue"},
        {"ref" : "user", "header" : "nUser"}
    ]
};



scwin.btn_getText_onclick = function (e) {
    let rtn = '';

    rtn = target1.getText();    
    wf_body_bottom.getObj("scwin").setReturnValue("selectbox label : " + rtn);    

    let targetElement = document.querySelector('[id*="target1_gridViewItemTable_gridView_main_div"]');

    if (!targetElement)
        wf_body_bottom.getObj("scwin").setReturnValue("SelectBox 의 아이템 리스트를 한번 오픈해야 아이템 리스트 정보를 가져올 수 있음");

    let textContent = targetElement.textContent;

    // 결과 출력
   wf_body_bottom.getObj("scwin").setReturnValue("Item Info : " + textContent);   
};



scwin.btn_setGridItemset_onclick = function (e) {
	target1.setGridItemset(info);
};
